(4090943, 585574, 84106, '<td valign="top">there are some dumb entries in this challenge, focus is good, face painting is good, BUT...</td>', 'there are some dumb entries in this challenge, focus is good, face painting is good, BUT...', '2007-09-15 00:47:02.000000', NULL, 1),
(4090945, 584868, 84106, '<td valign="top">Great - nailed it!  no technical faults</td>', 'Great - nailed it!  no technical faults', '2007-09-15 00:49:39.000000', NULL, 1),
(4090952, 585294, 84106, '<td valign="top">Great location, 2 openings:  little-help-over and the-big-one-in-the-background, worth an 8</td>', 'Great location, 2 openings:  little-help-over and the-big-one-in-the-background, worth an 8', '2007-09-15 00:56:08.000000', NULL, 1),
(4090953, 584710, 84106, '<td valign="top">Great focus, framing</td>', 'Great focus, framing', '2007-09-15 00:58:04.000000', NULL, 1),
(4090960, 584301, 84106, '<td valign="top">Ya gotta luv it!  Well done - all around - composition &amp; execution!</td>', 'Ya gotta luv it!  Well done - all around - composition & execution!', '2007-09-15 01:06:48.000000', NULL, 1),
(4090962, 583750, 84106, '<td valign="top">Great idea!  needs warmth of colour, and more skin!</td>', 'Great idea!  needs warmth of colour, and more skin!', '2007-09-15 01:09:11.000000', NULL, 1),
(4090967, 584299, 84106, '<td valign="top">OK! it''s a preying mantis.  ready 4 nectar sucking bugs - I finally got it!  Good composition, framing &amp; focus</td>', 'OK! it''s a preying mantis.  ready 4 nectar sucking bugs - I finally got it!  Good composition, framing & focus', '2007-09-15 01:13:34.000000', NULL, 1),
(4090969, 584343, 84106, '<td valign="top">Open the throttle!  Only suggestion:  rotate 90 ccw.  Good technicals.</td>', 'Open the throttle!  Only suggestion:  rotate 90 ccw.  Good technicals.', '2007-09-15 01:17:18.000000', NULL, 1),
(4090974, 585344, 84106, '<td valign="top">Cute, no Great!  Good colours, framing.</td>', 'Cute, no Great!  Good colours, framing.', '2007-09-15 01:21:18.000000', NULL, 1),
(4090989, 584840, 84106, '<td valign="top">Great shot!  But is it legal?  What are the white lines coming out?  Is this a composite?  Anyways, I like it!  Great colours.  Could have cropped or illuminated lower part more.</td>', 'Great shot!  But is it legal?  What are the white lines coming out?  Is this a composite?  Anyways, I like it!  Great colours.  Could have cropped or illuminated lower part more.', '2007-09-15 01:30:55.000000', NULL, 1),
(4090993, 585668, 84106, '<td valign="top">Exotic!  no technical faults.</td>', 'Exotic!  no technical faults.', '2007-09-15 01:34:50.000000', NULL, 1),
(4090999, 584799, 84106, '<td valign="top">Great!  I love it!  Great concept!  Perfect execution!  You get my first 10!</td>', 'Great!  I love it!  Great concept!  Perfect execution!  You get my first 10!', '2007-09-15 01:39:30.000000', NULL, 1),
(4091010, 585329, 84106, '<td valign="top">Poignant!  Great framing and lighting.</td>', 'Poignant!  Great framing and lighting.', '2007-09-15 01:46:47.000000', NULL, 1),
(4091011, 585492, 84106, '<td valign="top">Mesmerising!</td>', 'Mesmerising!', '2007-09-15 01:48:23.000000', NULL, 1),
(4091016, 584123, 83375, '<td valign="top">Ok, now that''s funny.</td>', 'Ok, now that''s funny.', '2007-09-15 01:50:29.000000', NULL, 1),
