(4091021, 585807, 81664, '<td valign="top">I wish the face was a bit more distinguishable. Great idea though!! Love the eery colors!</td>', 'I wish the face was a bit more distinguishable. Great idea though!! Love the eery colors!', '2007-09-15 01:53:18.000000', NULL, 1),
(4091022, 583800, 84106, '<td valign="top">Who do you think you are?  Good composition and focus and access to wild birds.  Great!</td>', 'Who do you think you are?  Good composition and focus and access to wild birds.  Great!', '2007-09-15 01:53:42.000000', NULL, 1),
(4091023, 585574, 81664, '<td valign="top">Oh I love this, how creative! Very funny and clever! 9!</td>', 'Oh I love this, how creative! Very funny and clever! 9!', '2007-09-15 01:54:44.000000', NULL, 1),
(4091031, 585287, 83375, '<td valign="top">Great tones and sharpness.</td>', 'Great tones and sharpness.', '2007-09-15 01:57:54.000000', NULL, 1),
